window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e635fd92f6ba3b3"]={"versions": [{"id": "FIG-8e635fd92f6ba3b3", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SEQ-LinkLossClient</code>) im Kontext des AUTOSAR Service-Oriented Middleware over IP Service Discovery Protocols (SOME/IP-SD). Das Diagramm visualisiert das Publish/Subscribe-Verhalten und die Erkennung eines Client-Reboots bei zwischenzeitlichem Verbindungsverlust (Link Loss) auf Client-Seite unter Vernachlässigung konkreter Timing-Parameter.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Kommunikationsentitäten mit Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Server</code>: SOME/IP-SD-Serverinstanz, führt Zustände zur Abonnentenverwaltung (<code>No registrations</code>, <code>updateRegistration()</code>, <code>Client Reboot Detected!</code>).\n</li><li><code>Client</code>: SOME/IP-SD-Clientinstanz mit lokaler Link-Zustandsüberwachung (<code>linkDown()</code>, <code>deleteEntries()</code>, <code>linkUp()</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>OfferService()</code>: Broadcast-/Multicast- bzw. Unicast-Nachricht des Servers zur Dienstankündigung.\n</li><li><code>SubscribeEventgroup [Session ID=x, Reboot = 0]</code>: Initiales Abonnement einer Eventgruppe durch den Client mit Session-ID <code>x</code> und gesetztem Reboot-Flag <code>Reboot = 0</code>.\n</li><li><code>updateRegistration()</code>: Interne Server-Aktion zur Registrierung des Abonnenten.\n</li><li><code>SubscribeEventgroupAck + Events()</code>: Bestätigung der Eventgruppen-Registrierung durch den Server inklusive nachfolgender Initial- bzw. Eventübertragung.\n</li><li><code>linkDown()</code>: Lokales Ereignis auf Client-Ebene zur Erkennung des Verbindungsabbruchs.\n</li><li><code>deleteEntries()</code>: Lokale Bereinigung der SD-Einträge/Abonnements auf Client-Ebene infolge des Link-Loss.\n</li><li><code>linkUp()</code>: Lokales Ereignis auf Client-Ebene bei Wiederherstellung des Links.\n</li><li><code>SubscribeEventgroup() [Session ID=1, Reboot=1]</code>: Erneute Eventgruppen-Subscription des Clients nach Link-Wiederherstellung mit zurückgesetzter Session-ID <code>1</code> und gesetztem Reboot-Flag <code>Reboot=1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Server signalisiert seine Dienstverfügbarkeit mittels <code>OfferService()</code>, während initial keine Registrierungen vorliegen (<code>No registrations</code>).\n</li><li>Der Client abonniert eine Eventgruppe über <code>SubscribeEventgroup [Session ID=x, Reboot = 0]</code>.\n</li><li>Der Server führt <code>updateRegistration()</code> aus und bestätigt das Abonnement mit <code>SubscribeEventgroupAck + Events()</code>.\n</li><li>Auf Client-Seite tritt ein Verbindungsverlust auf (<code>linkDown()</code>), woraufhin der Client seine lokalen SD-Einträge verwirft (<code>deleteEntries()</code>). Anschließend meldet die Verbindungsschicht <code>linkUp()</code>.\n</li><li>Nach Wiederverfügbarkeit des Links sendet der Server erneut <code>OfferService()</code>.\n</li><li>Der Client initiiert ein neues Abonnement mit <code>SubscribeEventgroup() [Session ID=1, Reboot=1]</code>.\n</li><li>Der Server erkennt anhand des Reboot-Flags und der zurückgesetzten Session-ID den Neustart/Re-Init des Clients (<code>Client Reboot Detected!</code>), aktualisiert die Registrierung via <code>updateRegistration()</code> und bestätigt erneut mit <code>SubscribeEventgroupAck + Events()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht den normativen SOME/IP-SD-Mechanismus zur Session-ID- und Reboot-Flag-Handhabung bei Verbindungsverlusten. Nach einem Link-Loss und bereinigter Subskriptionstabelle (<code>deleteEntries()</code>) startet der Client eine neue SD-Session (<code>Session ID=1</code>, <code>Reboot=1</code>). Entwickler müssen sicherstellen, dass bei <code>linkDown()</code> clientseitig alle Subscriptions invalidiert werden und der Server über den Reboot-Mechanismus verwaiste Registrierungen aktualisiert, um Inkonsistenzen im Event-Routing zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e4fc8f397518891b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SEQ-LinkLossClient</code>) im Kontext des AUTOSAR Service-Oriented Middleware over IP Service Discovery Protocols (SOME/IP-SD). Das Diagramm visualisiert das Publish/Subscribe-Verhalten und die Erkennung eines Client-Reboots bei zwischenzeitlichem Verbindungsverlust (Link Loss) auf Client-Seite unter Vernachlässigung konkreter Timing-Parameter.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Kommunikationsentitäten mit Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>Server</code>: SOME/IP-SD-Serverinstanz mit Abonnentenverwaltung (<code>No registrations</code>, <code>updateRegistration()</code>, <code>Client Reboot Detected!</code>).\n</li><li><code>Client</code>: SOME/IP-SD-Clientinstanz mit lokaler Link-Zustandsüberwachung (<code>linkDown()</code>, <code>deleteEntries()</code>, <code>linkUp()</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>OfferService()</code>: Dienstankündigung des Servers.\n</li><li><code>SubscribeEventgroup()[Session ID=x, Reboot = 0 or 1]</code>: Initiales Abonnement einer Eventgruppe durch den Client mit Session-ID <code>x</code> und Reboot-Flag <code>Reboot = 0 or 1</code>.\n</li><li><code>updateRegistration()</code>: Interne Server-Aktion zur Registrierung des Abonnenten.\n</li><li><code>SubscribeEventgroupAck+Events()</code>: Bestätigung der Eventgruppen-Registrierung durch den Server inklusive Eventübertragung.\n</li><li><code>linkDown()</code>: Lokales Ereignis auf Client-Ebene zur Erkennung des Verbindungsabbruchs.\n</li><li><code>deleteEntries()</code>: Lokale Bereinigung der SD-Einträge/Abonnements auf Client-Ebene.\n</li><li><code>linkUp()</code>: Lokales Ereignis auf Client-Ebene bei Wiederherstellung des Links.\n</li><li><code>SubscribeEventgroup()[Session ID=1, Reboot = 1]</code>: Erneute Eventgruppen-Subscription des Clients nach Link-Wiederherstellung mit initialer Session-ID <code>1</code> und gesetztem Reboot-Flag <code>Reboot = 1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Server kündigt den Dienst mittels <code>OfferService()</code> an (Ausgangszustand: <code>No registrations</code>).\n</li><li>Der Client abonniert die Eventgruppe mittels <code>SubscribeEventgroup()[Session ID=x, Reboot = 0 or 1]</code>.\n</li><li>Der Server führt <code>updateRegistration()</code> aus und bestätigt mit <code>SubscribeEventgroupAck+Events()</code>.\n</li><li>Ein Verbindungsabbruch auf Client-Ebene führt zur Signalisierung von <code>linkDown()</code> und dem Löschen lokaler Einträge (<code>deleteEntries()</code>). Nach Wiederverbindung erfolgt <code>linkUp()</code>.\n</li><li>Der Server sendet erneut <code>OfferService()</code>.\n</li><li>Der Client sendet ein neues Abonnement via <code>SubscribeEventgroup()[Session ID=1, Reboot = 1]</code>.\n</li><li>Der Server erkennt den Client-Reboot (<code>Client Reboot Detected!</code>), führt <code>updateRegistration()</code> durch und bestätigt mit <code>SubscribeEventgroupAck+Events()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht den normativen SOME/IP-SD-Mechanismus zur Session-ID- und Reboot-Flag-Handhabung bei Verbindungsverlusten. Nach einem Link-Loss und bereinigter Subskriptionstabelle (<code>deleteEntries()</code>) startet der Client eine neue SD-Session (<code>Session ID=1</code>, <code>Reboot=1</code>). Entwickler müssen sicherstellen, dass bei <code>linkDown()</code> clientseitig alle Subscriptions invalidiert werden und der Server über den Reboot-Mechanismus verwaiste Registrierungen aktualisiert, um Inkonsistenzen im Event-Routing zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8e635fd92f6ba3b3", "to": "FIG-e4fc8f397518891b", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Nachricht <code>SubscribeEventgroup</code>: Parameter <code>Reboot</code> bei der initialen Subscription von <code>[Session ID=x, Reboot = 0]</code> zu <code>[Session ID=x, Reboot = 0 or 1]</code> erweitert.\n</li><li>Nachricht <code>SubscribeEventgroup</code>: Klammerung bei der initialen Subscription von <code>SubscribeEventgroup [Session ID=x, Reboot = 0]</code> zu <code>SubscribeEventgroup()[Session ID=x, Reboot = 0 or 1]</code> vereinheitlicht.\n</li><li>Nachricht <code>SubscribeEventgroupAck + Events()</code>: Schreibweise redaktionell zu <code>SubscribeEventgroupAck+Events()</code> angepasst (Leerzeichen entfernt).\n</li><li>Optisches Redesign der Lifelines, Aktivierungsbalken und Kopfblöcke (abgerundete Ecken, geänderte Farbgebung).\n</li></ul>"}]};
